farmSmoke.expression:
let
  flake = builtins.getFlake "path:/home/brittonr/git/onix-core";
  system = "x86_64-linux";
  pkgs = import flake.inputs.nixpkgs { inherit system; };
  source = flake.inputs.nix-grpc-store;
in
import "${source}/tests/farm.nix" {
  inherit pkgs;
  nixPkgs = flake.inputs.nix.packages.${system} // {
    nix-everything = flake.nixosConfigurations.aspen1.config.nix.package;
  };
  niks3 = flake.inputs.niks3 // {
    nixosModules.niks3 = {
      imports = [ flake.inputs.niks3.nixosModules.niks3 ];
      services.niks3.serverPackage = flake.inputs.niks3.packages.${system}.niks3-server;
    };
  };
  mockOidc = flake.inputs.niks3.packages.${system}.mock-oidc-server;
  module = {
    imports = [
      "${source}/nixos/server.nix"
      "${source}/nixos/lb.nix"
      "${source}/nixos/client.nix"
    ];
    programs.nix-grpc-store.package = flake.packages.${system}.nix-grpc-store;
  };
}
